import { X509Certificate } from "node:crypto";

/**
 * Autorité racine Apple App Attestation (Apple_App_Attestation_Root_CA.pem,
 * publiée sur https://www.apple.com/certificateauthority/). Valide jusqu'en
 * 2045. L'empreinte SHA-256 est épinglée : toute altération du PEM empêche le
 * démarrage. À revérifier contre la source Apple lors de l'audit.
 */
export const APPLE_APP_ATTESTATION_ROOT_CA_PEM = `-----BEGIN CERTIFICATE-----

-----END CERTIFICATE-----
`;

export const APPLE_APP_ATTESTATION_ROOT_CA_SHA256 =
  "1C:B9:82:3B:A2:8B:A6:AD:2D:33:A0:06:94:1D:E2:AE:4F:51:3E:F1:D4:E8:31:B9:F7:E0:FA:7B:62:42:C9:32";

export function loadAppleAppAttestationRoot(): X509Certificate {
  const certificate = new X509Certificate(APPLE_APP_ATTESTATION_ROOT_CA_PEM);
  if (certificate.fingerprint256 !== APPLE_APP_ATTESTATION_ROOT_CA_SHA256) {
    throw new Error("empreinte de l'autorité racine Apple App Attestation inattendue");
  }
  if (!certificate.verify(certificate.publicKey)) {
    throw new Error("autorité racine Apple App Attestation : auto-signature invalide");
  }
  return certificate;
}
